// DUMMY. Tiap kategori: active (sedang andon), count (berapa kali), total (detik andon yg sudah selesai), startedAt.
// minutes = active ? (total + durasi andon berjalan) : total, dalam menit penuh.
// DUMMY: 1 menit = 5 detik supaya angka menit cepat berubah. Data asli: ganti jadi 60.
const DETIK_PER_MENIT = 5;
const CATS = {
  quality:   ['MA-3-LH','MA-8-RH','FIT-FINISH'],
  logistic:  ['MA-1-RH','SA-4','MA-11-LH'],
  equipment: ['MA-5-LH','SA-7','DYNO'],
  process:   ['MA-9-RH','SA-2','MA-14-LH']
};
let st = context.get('st');
if (!st) {
  st = {};
  for (const k in CATS) st[k] = { active:false, count:0, total:0, startedAt:0, station:'-' };
  context.set('st', st);
}
const now = Date.now();
for (const k in CATS) {
  const a = st[k];
  if (a.active) {
    // andon selesai: durasi 5-15 detik (dummy), masuk ke total
    if (now - a.startedAt > (5 + Math.random()*10) * 1000) {
      a.total += Math.round((now - a.startedAt) / 1000);
      a.active = false; a.station = '-';
    }
  } else if (Math.random() < 0.04) {
    // andon baru
    a.active = true; a.count++; a.startedAt = now;
    a.station = CATS[k][Math.floor(Math.random()*3)];
  }
}
const dt = {};
for (const k in CATS) {
  const a = st[k];
  const secs = a.total + (a.active ? Math.round((now - a.startedAt) / 1000) : 0);
  dt[k] = { active:a.active, count:a.count, minutes:Math.floor(secs / DETIK_PER_MENIT), station:a.station };
}
const r = (a,b) => Math.floor(Math.random()*(b-a+1))+a;
msg.payload = { target:92, assyOut:r(50,60), efficiency:r(85,95), jph:12, ct:5, handover:34, downtime:dt, ts:new Date().toISOString() };
return msg;
